CREATE proc [dbo].[uspLogin] @UserName as nvarchar(50), @Password as nvarchar(50) as Declare @ChkUserName as bit; set @ChkUserName = 0; Declare @DbPswd as nvarchar(50); Declare @DbUserName as nvarchar(50); Declare @LoginStatus as bit; set @LoginStatus = 0; declare @Waiter as nvarchar(50); Declare @CTSNoW as nvarchar(Max); set @CTSNoW = '0';  select @DbUserName = UserName from tbl_user where username = @UserName if (@DbUserName = @UserName) begin set @ChkUserName = 1; end  if (@ChkUserName = 1) begin select @DbPswd = pwd from tbl_user where username = @UserName  if (@DbPswd = @Password) begin set @LoginStatus = 1; end end  if (@LoginStatus = 1) begin Declare @CounterId as nvarchar(10); Declare @TiltId as nvarchar(10); set @TiltId = '2'; set @Waiter = @UserName; Declare @ShiftNo as nvarchar(50);  select @CounterId = id,@ShiftNo = Z_number from ShiftAmount where IsActive = 1 and TiltId = @TiltId set @CTSNoW = @CounterId + '#' + @TiltId + '#' + @ShiftNo + '#' + @Waiter end  if (@ChkUserName = 0 or @LoginStatus = 0) begin set @CTSNoW = 'Invalid User Name or Password'; end select @CTSNoW as Result